sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Só executa se um Centro de Distribuição foi selecionado
    if (current.centro_de_distribuicao.nil()) {
        gs.info('REGIAO-DEBUG: nenhum Centro de Distribuicao selecionado');
        return;
    }

    var regiao = current.centro_de_distribuicao.regiao.toString();

    var mapaRegiao = {
        'sudeste': 'Logistica - Sudeste',
        'sul': 'Logistica - Sul',
        'norte': 'Logistica - Norte',
        'nordeste': 'Logistica - Nordeste',
        'centro_oeste': 'Logistica - Centro-Oeste'
    };

    var nomeGrupo = mapaRegiao[regiao] || 'Logistica - Outras Regioes';

    gs.info('REGIAO-DEBUG: regiao lida = "' + regiao + '" | grupo calculado = "' + nomeGrupo + '"');

    var grupo = new GlideRecord('sys_user_group');
    grupo.addQuery('name', nomeGrupo);
    grupo.query();
    if (grupo.next()) {
        gs.info('REGIAO-DEBUG: grupo encontrado, sys_id = ' + grupo.sys_id);
        current.assignment_group = grupo.sys_id;
    } else {
        gs.info('REGIAO-DEBUG: NENHUM grupo encontrado com o nome "' + nomeGrupo + '"');
    }

})(current, previous);
